-- Adds references to existing carrier rows. Existing identities, fields, ACLs and RLS stay intact.
BEGIN;

ALTER TABLE public.carriers
  ADD COLUMN resource_links jsonb NOT NULL DEFAULT '[]'::jsonb;

COMMENT ON COLUMN public.carriers.resource_links IS
  'Ordered resource links: exact id, label, url, group objects; at most 50 per carrier.';

CREATE FUNCTION private.validate_carrier_resource_links()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO pg_catalog
AS $function$
DECLARE
  v_link jsonb;
  v_id text;
  v_ids uuid[] := ARRAY[]::uuid[];
  v_label text;
  v_url text;
  v_authority text;
  v_host text;
  v_parts text[];
  v_octet text;
  v_address inet;
  -- ECMAScript String.trim whitespace, shared with the form schema.
  v_trim_chars constant text := U&'\0009\000a\000b\000c\000d\0020\00a0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200a\2028\2029\202f\205f\3000\feff';
BEGIN
  IF NEW.resource_links IS NULL OR jsonb_typeof(NEW.resource_links) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Carrier resource links must be a JSON array' USING ERRCODE = '23514';
  END IF;
  IF jsonb_array_length(NEW.resource_links) > 50 THEN
    RAISE EXCEPTION 'A carrier may have at most 50 resource links' USING ERRCODE = '23514';
  END IF;

  FOR v_link IN SELECT value FROM jsonb_array_elements(NEW.resource_links) LOOP
    IF jsonb_typeof(v_link) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'Each carrier resource link must be an object' USING ERRCODE = '23514';
    END IF;
    IF NOT (v_link ?& ARRAY['id', 'label', 'url', 'group'])
       OR (v_link - 'id' - 'label' - 'url' - 'group') <> '{}'::jsonb
       OR jsonb_typeof(v_link->'id') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_link->'label') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_link->'url') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_link->'group') IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION 'Carrier resource links require exactly four string fields: id, label, url, group'
        USING ERRCODE = '23514';
    END IF;

    v_id := v_link->>'id';
    IF v_id !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'Carrier resource link ids must be UUIDs' USING ERRCODE = '23514';
    END IF;
    IF v_id::uuid = ANY(v_ids) THEN
      RAISE EXCEPTION 'Carrier resource link ids must be unique' USING ERRCODE = '23514';
    END IF;
    v_ids := array_append(v_ids, v_id::uuid);

    v_label := v_link->>'label';
    IF char_length(v_label) NOT BETWEEN 1 AND 120 OR v_label <> btrim(v_label, v_trim_chars) THEN
      RAISE EXCEPTION 'Carrier resource labels must be trimmed and contain 1 to 120 characters'
        USING ERRCODE = '23514';
    END IF;
    IF v_link->>'group' NOT IN ('quick_links', 'guides_training') THEN
      RAISE EXCEPTION 'Unsupported carrier resource group' USING ERRCODE = '23514';
    END IF;

    v_url := v_link->>'url';
    IF char_length(v_url) NOT BETWEEN 1 AND 2048
       OR v_url !~* '^https?://'
       OR strpos(v_url, chr(92)) > 0
       OR v_url ~ U&'[\0001-\0020\007f-\009f\00a0\1680\2000-\200a\2028\2029\202f\205f\3000\feff]' THEN
      RAISE EXCEPTION 'Carrier resource URLs must be absolute HTTP(S) URLs without whitespace or control characters'
        USING ERRCODE = '23514';
    END IF;

    v_authority := substring(v_url FROM '^[Hh][Tt][Tt][Pp][Ss]?://([^/?#]+)');
    IF v_authority IS NULL OR strpos(v_authority, '@') > 0 THEN
      RAISE EXCEPTION 'Carrier resource URLs require a host and cannot include credentials'
        USING ERRCODE = '23514';
    END IF;

    IF left(v_authority, 1) = '[' THEN
      v_parts := regexp_match(v_authority, '^\[([0-9A-Fa-f:.]+)\](?::([0-9]{1,5}))?$');
      IF v_parts IS NULL THEN
        RAISE EXCEPTION 'Invalid carrier resource URL host or port' USING ERRCODE = '23514';
      END IF;
      BEGIN
        v_address := v_parts[1]::inet;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'Invalid carrier resource IPv6 host' USING ERRCODE = '23514';
      END;
      IF family(v_address) <> 6 THEN
        RAISE EXCEPTION 'Invalid carrier resource IPv6 host' USING ERRCODE = '23514';
      END IF;
    ELSE
      v_parts := regexp_match(v_authority, '^([^:]+)(?::([0-9]{1,5}))?$');
      IF v_parts IS NULL THEN
        RAISE EXCEPTION 'Invalid carrier resource URL host or port' USING ERRCODE = '23514';
      END IF;
      v_host := v_parts[1];
      IF char_length(v_host) > 253
         OR v_host !~ '^[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*\.?$' THEN
        RAISE EXCEPTION 'Carrier resource URL hosts must be ASCII DNS names or IP addresses'
          USING ERRCODE = '23514';
      END IF;
      -- Avoid browser-specific abbreviated, octal or hexadecimal IPv4 interpretation.
      IF v_host ~ '(^|\.)([0-9]+|0[xX][0-9A-Fa-f]+)\.?$' THEN
        IF v_host !~ '^(0|[1-9][0-9]{0,2})(\.(0|[1-9][0-9]{0,2})){3}$' THEN
          RAISE EXCEPTION 'Carrier resource IPv4 hosts require four decimal octets' USING ERRCODE = '23514';
        END IF;
        FOREACH v_octet IN ARRAY string_to_array(v_host, '.') LOOP
          IF v_octet::integer > 255 THEN
            RAISE EXCEPTION 'Invalid carrier resource IPv4 host' USING ERRCODE = '23514';
          END IF;
        END LOOP;
      END IF;
    END IF;
    IF v_parts[2] IS NOT NULL AND v_parts[2]::integer > 65535 THEN
      RAISE EXCEPTION 'Invalid carrier resource URL port' USING ERRCODE = '23514';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$function$;

-- Trigger execution needs no client EXECUTE or private-schema USAGE grant.
REVOKE ALL ON FUNCTION private.validate_carrier_resource_links()
  FROM PUBLIC, anon, authenticated, service_role;

CREATE TRIGGER carriers_resource_links_validate
BEFORE INSERT OR UPDATE OF resource_links ON public.carriers
FOR EACH ROW EXECUTE FUNCTION private.validate_carrier_resource_links();

COMMIT;
